type Monoid[T any] interface{ Combine(T, T) T }

func Identity[T any]() T { var zero T; return zero }

func Fold[T any](xs []T, m Monoid[T]) T {
    acc := Identity[T]()
    for _, x := range xs { acc = m.Combine(acc, x) }   // associative: regrouping is safe
    return acc
}

type Score int
func (s Score) Combine(a, b Score) Score { return a + b }

var total = Fold([]Score{1, 2, 3}, Score(0))
